package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextUniversalFamilyInspection.*;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.exception.ContextProductionCommitException;

/** A disjunctive product stays whole until exact private evidence selects a branch. */
final class ContextAuthorityDisjunctiveHead {
    static int checks;static final int WORK=64000000;
    static void require(boolean yes,String why){++checks;if(!yes)throw new AssertionError(why);}
    static final class Expected {
        final Set<Source> locals=new HashSet<>(),donors=new HashSet<>(),bridges=new HashSet<>();
        final SemanticTermSnapshot x,head,other;final Source premise;Source dm,dt;final boolean negative;
        Expected(ContextProductionCandidate.Staged a,boolean negative,int mode){
            this.negative=negative;for(Entry e:a.staged.primary)locals.add(e.source);
            Entry base=a.staged.primary.stream().filter(e->!e.source.equals(a.candidate)).findFirst().get();premise=base.source;x=base.clauses.get(0).literals.get(0).arguments.get(0).value;
            SemanticTermSnapshot h=null,o=null;
            for(org.kanger.ContextProductionNativeBinding.Snapshot cut:a.foreign)for(Entry e:cut.primary){require(e.clauses.size()==1,"each private statement has one whole clause");Clause c=e.clauses.get(0);if(c.literals.size()==3){Map<String,Atom> atoms=new HashMap<>();for(Atom atom:c.literals)atoms.put(atom.predicate,atom);Atom out=atoms.get("out"),mid=atoms.get("mid"),tail=atoms.get("tail");require(atoms.size()==3&&out!=null&&mid!=null&&tail!=null&&out.positive==negative&&mid.positive!=negative&&tail.positive!=negative&&c.variables.size()==3,"one whole three-literal disjunctive Bridge");Set<Integer> slots=new HashSet<>();for(Slot slot:out.arguments){require(slot.variable>=0,"universal Bridge input");slots.add(slot.variable);}require(slots.size()==3&&mid.arguments.size()==1&&mid.arguments.get(0).variable<0&&tail.arguments.size()==1&&tail.arguments.get(0).variable==out.arguments.get(0).variable,"literal mid and first-input tail preserve one disjunction");h=mid.arguments.get(0).value;bridges.add(e.source);}
                else{require(c.literals.size()==1,"private donor or Deny is unit");Atom atom=c.literals.get(0);if(atom.predicate.equals("q")){require(c.variables.size()==3&&atom.positive!=negative,"independent universal q donor");donors.add(e.source);}else{require(atom.positive==negative&&atom.arguments.size()==1&&c.variables.isEmpty(),"opposite ground Deny");if(atom.predicate.equals("mid"))dm=e.source;else{require(atom.predicate.equals("tail"),"known Deny endpoint");dt=e.source;}if(mode==4&&atom.predicate.equals("mid")||mode==5&&atom.predicate.equals("tail"))o=atom.arguments.get(0).value;}}
            }
            head=h;other=o;require(locals.size()==2&&locals.contains(a.candidate)&&donors.size()==3&&bridges.size()==2&&h!=null&&!h.semanticallyEquals(x),"whole X2, three donors, two distinct whole Bridges and exact head literal");require(donors.stream().map(s->s.context).distinct().count()==3&&bridges.stream().map(s->s.context).distinct().count()==2,"independent private origins");
            require((dm!=null)==(mode==1||mode==3||mode==4||mode==5)&&(dt!=null)==(mode==2||mode==3||mode==4||mode==5),"exact Deny topology per case");
            if(mode>=4)require(o!=null&&!o.semanticallyEquals(x)&&!o.semanticallyEquals(h),"nonmatching private endpoint value");
        }
        Set<Source> set(Source... extra){Set<Source> s=new HashSet<>(locals);s.addAll(Arrays.asList(extra));return s;}
        Set<Set<Source>> alternatives(Source extra){Set<Set<Source>> result=new HashSet<>();for(Source q:donors)for(Source b:bridges){Set<Source> s=set(q,b);if(extra!=null)s.add(extra);result.add(s);}return result;}
    }
    static boolean ground(Atom a,SemanticTermSnapshot value){return a.arguments.size()==1&&a.arguments.get(0).variable<0&&a.arguments.get(0).value.semanticallyEquals(value);}
    static boolean counter(Clause c,Expected e){if(c.variables.size()!=2||c.literals.size()!=1)return false;Atom a=c.literals.get(0);return a.arguments.size()==3&&a.arguments.get(0).variable<0&&a.arguments.get(0).value.semanticallyEquals(e.x)&&a.arguments.get(1).variable>=0&&a.arguments.get(2).variable>=0&&a.arguments.get(1).variable!=a.arguments.get(2).variable;}
    static void disjunction(ContextUniversalUnitRounds.Frontier f,Expected e,int count){Set<Set<Source>> actual=new HashSet<>();for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==2){Map<String,Atom> atoms=new HashMap<>();for(Atom a:row.clause.literals)atoms.put(a.predicate,a);if(!atoms.keySet().equals(new HashSet<>(Arrays.asList("mid","tail"))))continue;require(row.clause.variables.isEmpty()&&atoms.get("mid").positive!=e.negative&&atoms.get("tail").positive!=e.negative&&ground(atoms.get("mid"),e.head)&&ground(atoms.get("tail"),e.x)&&row.support.depth==3&&actual.add(row.support.sources),"whole ground disjunction with exact cumulative depth and unique Source alternative");}
        require(actual.size()==count&&(count==0||actual.equals(e.alternatives(null))),"all six exact disjunction alternatives, never separate unconditional heads");}
    static void units(ContextUniversalUnitRounds.Frontier f,Expected e,String predicate,int depth,SemanticTermSnapshot value,Set<Set<Source>> expected){Set<Set<Source>> actual=new HashSet<>();int n=0;for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1){Atom atom=row.clause.literals.get(0);if(!atom.predicate.equals(predicate))continue;++n;require(atom.positive!=e.negative||predicate.equals("p1"),"exact selected head sign");if(predicate.equals("p1"))require(atom.positive,"positive displaced premise");require(row.clause.variables.isEmpty()&&ground(atom,value)&&row.support.depth==depth&&actual.add(row.support.sources),"exact selected ground unit, depth and unique support");}require(n==expected.size()&&actual.equals(expected),"all independently enumerated alternatives for "+predicate);}
    static void out(ContextUniversalUnitRounds.Frontier f,Expected e){Set<Set<Source>> expected=new HashSet<>(),actual=new HashSet<>();for(Source q:e.donors)expected.add(e.set(q));for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("out")){Atom a=row.clause.literals.get(0);require(a.positive!=e.negative&&a.arguments.size()==3&&row.clause.variables.size()==2&&a.arguments.get(0).variable<0&&a.arguments.get(0).value.semanticallyEquals(e.x)&&a.arguments.get(1).variable>=0&&a.arguments.get(2).variable>=0&&a.arguments.get(1).variable!=a.arguments.get(2).variable&&row.support.depth==2&&actual.add(row.support.sources),"three independently supported out schemas preserve both free coordinates");}require(actual.equals(expected),"exact out support alternatives");}
    static void consistent(Result r,Expected e,int mode){require(r.status==Status.CONSISTENT&&r.collision==null&&r.certificate!=null&&r.completedBarriers==(mode==0?3:mode==5?5:4),"case-specific stable-family certificate and barrier count");ContextUniversalFamilyModel.Certificate cert=r.certificate;require(cert.cuts.size()==6+(e.dm==null?0:1)+(e.dt==null?0:1)&&cert.cuts.size()==cert.input.cuts.size(),"all exact family cuts");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut cut:cert.cuts){require(cut.receipt.verified&&cut.receipt.input==cert.input&&cut.model.ledger==cut.receipt.closureStep.input,"model exact private closure");receipts.add(cut.receipt);models.add(cut.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"independent all-values model recheck");
        out(cert.input,e);disjunction(cert.input,e,6);Set<Set<Source>> empty=Collections.emptySet();boolean mid=mode==2||mode==4,tail=mode==1||mode==5;
        units(cert.input,e,"mid",4,e.head,mid?e.alternatives(e.dt):empty);units(cert.input,e,"tail",4,e.x,tail?e.alternatives(e.dm):empty);
        Set<Set<Source>> p1=new HashSet<>();if(mode==5)for(Source q:e.donors)for(Source b:e.bridges){Set<Source> s=e.set(q,b,e.dm,e.dt);require(s.remove(e.premise)&&s.size()==5,"displaced p1 requires both Denies but not original premise");p1.add(s);}units(cert.input,e,"p1",4,e.other,p1);
        require(cert.input.products.size()==(mode==0?23:mode==5?55:39),"exact full residual frontier size");require(cert.input.products.stream().filter(row->row.clause.literals.size()==1).count()==(mode==0?3:mode==5?15:9),"no other unit imports or premature branch choices");
    }
    static void collision(Result r,Expected e,boolean exactLocal){require(r.status==Status.COLLISION&&r.certificate==null&&r.completedBarriers==4&&r.collision.oppositions.size()==18,"complete fourth-barrier q/mid/tail collision");Map<Set<Source>,Set<String>> routes=new HashMap<>();for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&p.support.depth==5&&p.leftSupport.depth==0&&p.leftSupport.sources.size()==1&&p.rightSupport.depth==4&&p.rightSupport.sources.size()==5&&p.left.literals.size()==1&&p.right.literals.size()==1,"whole depth5 opposition after evidence selects both branches");Atom l=p.left.literals.get(0),rr=p.right.literals.get(0);require(l.predicate.equals(rr.predicate)&&l.positive!=rr.positive,"opposite same endpoint");if(l.predicate.equals("q"))require(l.positive!=e.negative&&p.left.variables.size()==3&&counter(p.right,e),"universal donor meets counter-q with two independent free slots");else require(l.positive==e.negative&&p.right.variables.isEmpty()&&ground(l,l.predicate.equals("mid")?e.head:e.x)&&ground(rr,l.predicate.equals("mid")?e.head:e.x),"selected ground endpoint proof");
            Set<Source> local=new HashSet<>(),foreign=new HashSet<>();for(Source s:p.support.sources)(s.localX?local:foreign).add(s);require(local.size()==2&&foreign.size()==4&&foreign.contains(e.dm)&&foreign.contains(e.dt)&&p.support.sources.size()==6,"both exact Denies necessary in every full refutation");if(exactLocal)require(local.equals(e.locals),"exact fresh local sources");Set<Source> pair=new HashSet<>(foreign);pair.remove(e.dm);pair.remove(e.dt);require(pair.size()==2&&pair.stream().anyMatch(e.donors::contains)&&pair.stream().anyMatch(e.bridges::contains)&&routes.computeIfAbsent(pair,k->new HashSet<>()).add(l.predicate),"unique endpoint per exact donor/Bridge pair");}
        require(routes.size()==6&&routes.values().stream().allMatch(v->v.equals(new HashSet<>(Arrays.asList("q","mid","tail")))),"all six pairs at all three endpoints");}
    static void barriers(ContextProductionCandidate.Staged a,Expected e){ContextUniversalUnitRounds.Frontier initial=ContextUniversalUnitRounds.start(a.staged,a.foreign,WORK);ContextUniversalUnitRounds.Barrier first=ContextUniversalUnitRounds.merge(initial,ContextUniversalAuthorityChain.pass(initial,16),16,WORK);require(first.status==ContextUniversalUnitRounds.Status.MERGED&&first.changed&&initial.products.isEmpty(),"immutable first barrier");out(first.frontier,e);disjunction(first.frontier,e,0);int saved=first.frontier.products.size();ContextUniversalUnitRounds.Barrier second=ContextUniversalUnitRounds.merge(first.frontier,ContextUniversalAuthorityChain.pass(first.frontier,16),16,WORK);require(second.status==ContextUniversalUnitRounds.Status.MERGED&&second.changed&&first.frontier.products.size()==saved,"immutable second barrier");out(second.frontier,e);disjunction(second.frontier,e,6);require(second.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==3,"second barrier exports no independently asserted disjunct");}
    static ContextUniversalCandidate.Evaluation inspect(ContextSevenPremiseNativeWriteRunner.Fixture f,String text,int rounds)throws Exception{return f.db.qualifyUniversalProductionCandidate(f.root,text,1000,rounds,16,16,65536,1000000,WORK,500000,WORK);}
    static void one(boolean negative,boolean reverse,int mode,boolean nativePath)throws Exception{
        Path dir=Files.createTempDirectory("disjunctive-head-");System.setProperty("user.home",dir.toString());String sign=negative?"~":"";List<String> names=new ArrayList<>();
        for(String name:new String[]{"A1","A2","A3"}){ContextAuthorityChain.create(dir,name,"!@x @y @z "+sign+"q(x,y,z);");names.add(name);}for(String name:new String[]{"Bridge1","Bridge2"}){ContextAuthorityChain.create(dir,name,"!@x @y @z "+sign+"out(x,y,z)->"+sign+"mid(2)||"+sign+"tail(x);");names.add(name);}
        if(mode==1||mode==3||mode==4||mode==5){ContextAuthorityChain.create(dir,"DenyMid","!"+(negative?"":"~")+(mode==4?"mid(9);":"mid(2);"));names.add("DenyMid");}if(mode==2||mode==3||mode==4||mode==5){ContextAuthorityChain.create(dir,"DenyTail","!"+(negative?"":"~")+(mode==5?"tail(9);":"tail(1);"));names.add("DenyTail");}if(reverse)Collections.reverse(names);
        String text="!@x @y @z "+sign+"q(x,y,z)&&~p1(x)->"+sign+"out(x,y,z);";boolean conflict=mode==3;Set<String> origins;List<RevisionRef> pins;long settled;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            require(f.root.compile("!~p1(1);",null,false),"original premise");for(String name:names)f.db.connectContext(name);f.db.saveConnections(f.root);ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> initialOrigins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);require(initialOrigins.size()==1&&pins.size()==names.size(),"only original premise and exact saved topology");
            ContextUniversalCandidate.Evaluation diagnostic=inspect(f,text,16);require(diagnostic.status==(conflict?Status.COLLISION:Status.CONSISTENT),"disjunction mode"+mode+": "+diagnostic.reason);Expected expected=new Expected(diagnostic.artifact,negative,mode);
            Entry candidate=diagnostic.artifact.staged.primary.stream().filter(e->e.source.equals(diagnostic.artifact.candidate)).findFirst().get();require(candidate.clauses.size()==1&&candidate.clauses.get(0).variables.size()==3&&candidate.clauses.get(0).literals.size()==3,"whole independent three-variable candidate");
            if(conflict)collision(diagnostic.qualification,expected,true);else consistent(diagnostic.qualification,expected,mode);barriers(diagnostic.artifact,expected);
            ContextUniversalCandidate.Evaluation stopped=inspect(f,text,1);require(stopped.status==Status.INCOMPLETE&&stopped.qualification.collision==null&&stopped.qualification.certificate==null&&stopped.reason.contains("common round limit"),"round cap never exposes a partial verdict");require(f.db.getRevision()==revision&&f.root.getRules().size()==rules&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"diagnostics preserve exact physical state");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(text,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(conflict){require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"fresh native-child conflict independently audited");collision(failure.getFamilyAudit().verdict,expected,false);}else require(failure==null,"actual native disjunctive family accepted");}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,text,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(conflict?DB.ProductionWriteStatus.COLLISION:DB.ProductionWriteStatus.PUBLISHED),"fresh public writer settles mode"+mode+": "+result.status+" / "+result.trial.reason);require(result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial&&result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"fresh audit and exact physical revision references");Expected fresh=new Expected(result.trial.artifact,negative,mode);if(conflict)collision(result.trial.qualification,fresh,true);else{require(result.audit.oppositions.isEmpty(),"compatible disjunction has no collision attribution");consistent(result.trial.qualification,fresh,mode);}}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);origins=ContextSevenPremiseNativeWriteRunner.origins(after);settled=f.db.getRevision();require(ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"exact saved pin order unchanged");if(conflict)require(settled==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint)&&origins.equals(initialOrigins),"both-Deny refusal preserves exact original theory");else{require(settled>revision&&after.primary.size()==2&&origins.size()==2&&origins.containsAll(initialOrigins),"only one whole candidate published");ContextProductionNativeBinding.Result bound=ContextProductionNativeBinding.bind(f.root,after,WORK,500000);require(bound.bound&&bound.snapshot.primary.size()==2&&bound.snapshot.primary.stream().anyMatch(e->e.clauses.size()==1&&e.clauses.get(0).equivalent(candidate.clauses.get(0))),"actual published primary is exact requested rule");require(bound.snapshot.primary.stream().allMatch(e->e.clauses.size()==1&&(e.clauses.get(0).equivalent(candidate.clauses.get(0))||e.clauses.get(0).literals.size()==1&&e.clauses.get(0).literals.get(0).predicate.equals("p1")&&!e.clauses.get(0).literals.get(0).positive)),"no disjunct, private assertion or displaced p1 imported as primary");}
            System.out.println("DISJUNCTIVE mode="+mode+" negative="+negative+" reverse="+reverse+" native="+nativePath+" barriers="+diagnostic.qualification.completedBarriers);
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){ContextProductionInventory inv=ContextSevenPremiseNativeWriteRunner.inventory(f);require(f.db.getRevision()>=settled&&inv.primary.size()==(conflict?1:2)&&ContextSevenPremiseNativeWriteRunner.origins(inv).equals(origins)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary reopen retains exact source theory and topology");}
    }
    static void run(boolean negative,boolean reverse,String marker){try{for(int mode=0;mode<6;mode++)for(boolean nativePath:new boolean[]{false,true})one(negative,reverse,mode,nativePath);System.out.println(marker+" checks="+(checks+ContextAuthorityChain.checks));System.exit(0);}catch(Throwable failure){failure.printStackTrace();System.exit(1);}}
}
